}
html{font-size:16px;scroll-behavior:smooth}
body{font-family:var(--font);color:var(--text);background:var(--bg);line-height:1.6;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:none;background:none}
img{display:block;max-width:100%}
.container{max-width:var(--max-w);margin:0 auto;padding:0 24px}

/* ─── HEADER ─── */
.header{background:var(--bg-white);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:100}
.header-inner{display:flex;align-items:center;justify-content:space-between;height:64px}
.logo{font-size:18px;font-weight:700;letter-spacing:-.3px;display:flex;align-items:center;gap:8px}
.logo svg{width:28px;height:28px}
.logo .blog-badge{font-size:12px;font-weight:500;color:var(--accent);border:1px solid var(--accent);border-radius:var(--radius-pill);padding:2px 8px;margin-left:4px}
.nav-main{display:flex;align-items:center;gap:4px}
.nav-link{padding:8px 14px;font-size:14px;font-weight:500;color:var(--text-secondary);border-radius:var(--radius);transition:color .15s,background .15s}
.nav-link:hover{color:var(--text);background:rgba(0,0,0,.04)}
.nav-link.has-dropdown{position:relative}
.nav-link .chevron{width:12px;height:12px;margin-left:4px;opacity:.5;transition:transform .2s}
.nav-link.active .chevron{transform:rotate(180deg)}
.nav-actions{display:flex;align-items:center;gap:8px}
.btn-ghost{padding:8px 14px;font-size:14px;font-weight:500;color:var(--text-secondary);border-radius:var(--radius);transition:all .15s}
.btn-ghost:hover{color:var(--text);background:rgba(0,0,0,.04)}
.btn-login{padding:8px 16px;font-size:14px;font-weight:500;color:var(--text);border-radius:var(--radius);transition:all .15s}
.btn-login:hover{background:rgba(0,0,0,.04)}
.btn-signup{padding:8px 18px;font-size:14px;font-weight:600;color:#fff;background:var(--text);border-radius:var(--radius);transition:background .15s}
.btn-signup:hover{background:#333}

/* Mega Menu */
.mega-menu{position:absolute;top:100%;left:50%;transform:translateX(-50%);background:var(--bg-white);border:1px solid var(--border);border-radius:var(--radius-lg);box-shadow:var(--shadow-lg);padding:28px 32px;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .2s,visibility .2s;min-width:560px;z-index:200}
.mega-menu.show{opacity:1;visibility:visible;pointer-events:auto}
.mega-menu-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:28px}
.mega-menu-col h4{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--text-tertiary);margin-bottom:12px}
.mega-menu-col a{display:block;font-size:13.5px;font-weight:500;color:var(--text);padding:5px 0;transition:color .12s}
.mega-menu-col a:hover{color:var(--accent)}
.mega-menu-col .item-desc{font-size:11.5px;color:var(--text-tertiary);font-weight:400;margin-top:1px}

/* Dropdown wrapper */
.dropdown-wrapper{position:relative}

/* Mobile menu toggle */
.mobile-toggle{display:none;padding:8px;border-radius:var(--radius)}
.mobile-toggle span{display:block;width:20px;height:2px;background:var(--text);margin:4px 0;transition:all .2s}

/* ─── CATEGORY FILTERS ─── */
