.filters-title{font-size:32px;font-weight:800;letter-spacing:-.5px}
.search-box{position:relative;width:260px}
.search-box input{width:100%;padding:10px 14px 10px 38px;font-size:14px;border:1px solid var(--border);border-radius:var(--radius);background:var(--bg-white);transition:border-color .15s,box-shadow .15s;font-family:var(--font)}
