.pills{display:flex;flex-wrap:wrap;gap:8px}
.pill{padding:8px 18px;font-size:13.5px;font-weight:500;border-radius:var(--radius-pill);border:1px solid var(--border);background:var(--bg-white);color:var(--text-secondary);transition:all .18s;white-space:nowrap}
.pill:hover{border-color:var(--border-hover);color:var(--text)}
.pill.active{background:var(--text);color:#fff;border-color:var(--text)}

