.featured-card.large h2{font-size:30px;letter-spacing:-.5px;line-height:1.25}
.featured-card p{font-size:15px;line-height:1.65;color:var(--text-secondary);flex:1}
.featured-card.large p{font-size:16px}
.featured-card .card-author{display:flex;align-items:center;gap:10px;margin-top:20px;padding-top:16px;border-top:1px solid var(--border)}
