.card-author-name{font-size:13.5px;font-weight:500}
.featured-label{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--accent);margin-bottom:8px}

/* Stats strip inside featured */
.stats-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:20px;padding-top:20px;border-top:1px solid var(--border)}
.stat-item .stat-value{font-size:24px;font-weight:800;color:var(--accent);letter-spacing:-.5px}
.stat-item .stat-label{font-size:12px;color:var(--text-tertiary);line-height:1.4;margin-top:2px}

/* ─── LATEST NEWS ─── */
