.btn-secondary:hover{background:rgba(255,255,255,.2)}

.enterprise-strip{margin-top:20px;background:var(--bg-white);border:1px solid var(--border);border-radius:var(--radius-lg);padding:28px 36px;display:flex;align-items:center;justify-content:space-between;gap:24px}
