.btn-enterprise:hover{background:rgba(0,114,245,.06)}

/* ─── FOOTER ─── */
.footer{border-top:1px solid var(--border);padding:56px 0 32px;background:var(--bg-white)}
.footer-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:24px}
.footer-col h5{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--text-tertiary);margin-bottom:14px}
.footer-col a{display:block;font-size:13px;color:var(--text-secondary);padding:3px 0;transition:color .12s}
.footer-col a:hover{color:var(--text)}
.footer-bottom{margin-top:40px;padding-top:24px;border-top:1px solid var(--border);display:flex;align-items:center;justify-content:space-between}
.footer-bottom .status{display:flex;align-items:center;gap:6px;font-size:13px;color:var(--text-tertiary)}
.footer-bottom .status .dot-green{width:7px;height:7px;border-radius:50%;background:#22C55E}
.footer-copyright{font-size:12.5px;color:var(--text-tertiary)}

/* ─── RESPONSIVE ─── */
@media(max-width:1024px){
  .featured-grid{grid-template-columns:1fr}
  .featured-card.large{grid-row:auto}
  .news-grid{grid-template-columns:repeat(2,1fr)}
  .footer-grid{grid-template-columns:repeat(3,1fr)}
  .cta-banner{grid-template-columns:1fr;text-align:center}
  .cta-buttons{justify-content:center}
  .mega-menu{min-width:420px}
}
@media(max-width:768px){
  .nav-main,.nav-actions .btn-ghost{display:none}
  .mobile-toggle{display:flex;flex-direction:column;justify-content:center;align-items:center}
  .filters-top{flex-direction:column;align-items:flex-start}
  .search-box{width:100%}
  .filters-title{font-size:26px}
