const INITIAL_COUNT = 8;
let visibleCount = INITIAL_COUNT;
let activeCategory = 'all';
let searchQuery = '';

const newsGrid = document.getElementById('newsGrid');
const noResults = document.getElementById('noResults');
const showMoreWrap = document.getElementById('showMoreWrap');
const showMoreBtn = document.getElementById('showMoreBtn');
const searchInput = document.getElementById('searchInput');
const categoryPills = document.getElementById('categoryPills');
const featuredSection = document.getElementById('featuredSection');

function getFilteredPosts() {
  return allPosts.filter(p => {
    const matchCat = activeCategory === 'all' || p.category === activeCategory;
    const q = searchQuery.toLowerCase();
    const matchSearch = !q || p.title.toLowerCase().includes(q) || p.excerpt.toLowerCase().includes(q) || p.author.toLowerCase().includes(q) || p.category.toLowerCase().includes(q);
    return matchCat && matchSearch;
  });
}

function renderCards() {
  const filtered = getFilteredPosts();
  const visible = filtered.slice(0, visibleCount);
  newsGrid.innerHTML = visible.map((p, i) => `
    <article class="post-card" style="animation-delay:${i * .04}s" data-category="${p.category}">
      <span class="card-tag">${p.category}</span>
      <div class="card-date">${p.date}</div>
      <h3>${p.title}</h3>
      <p class="card-excerpt">${p.excerpt}</p>
      <div class="card-author">
        <div class="avatar" style="background:${p.color}">${p.initials}</div>
        <span class="card-author-name">${p.author}</span>
      </div>
    </article>
  `).join('');

  const hasResults = visible.length > 0;
  noResults.classList.toggle('show', !hasResults);
  newsGrid.style.display = hasResults ? '' : 'none';
  showMoreWrap.style.display = (filtered.length > visibleCount && hasResults) ? '' : 'none';

  // Hide featured when filtering
  const isFiltering = activeCategory !== 'all' || searchQuery.length > 0;
  featuredSection.style.display = isFiltering ? 'none' : '';
}

// Category pills
categoryPills.addEventListener('click', e => {
  const pill = e.target.closest('.pill');
  if (!pill) return;
  categoryPills.querySelectorAll('.pill').forEach(p => p.classList.remove('active'));
  pill.classList.add('active');
  activeCategory = pill.dataset.category;
  visibleCount = INITIAL_COUNT;
  renderCards();
});

// Search
let debounce;
searchInput.addEventListener('input', e => {
  clearTimeout(debounce);
  debounce = setTimeout(() => {
    searchQuery = e.target.value.trim();
    visibleCount = INITIAL_COUNT;
    renderCards();
  }, 200);
});

// Show more
showMoreBtn.addEventListener('click', () => {
  visibleCount += 4;
  renderCards();
});

// Mega menus
document.querySelectorAll('[data-dropdown]').forEach(btn => {
  const menu = document.getElementById('mega-' + btn.dataset.dropdown);
  let timer;
  const show = () => { clearTimeout(timer); btn.classList.add('active'); menu.classList.add('show'); };
  const hide = () => { timer = setTimeout(() => { btn.classList.remove('active'); menu.classList.remove('show'); }, 200); };
  btn.addEventListener('mouseenter', show);
  btn.addEventListener('mouseleave', hide);
  menu.addEventListener('mouseenter', show);
  menu.addEventListener('mouseleave', hide);
  btn.addEventListener('click', () => menu.classList.contains('show') ? hide() : show());
});

// Close menus on outside click
document.addEventListener('click', e => {
  if (!e.target.closest('.dropdown-wrapper')) {
    document.querySelectorAll('.mega-menu').forEach(m => m.classList.remove('show'));
    document.querySelectorAll('.has-dropdown').forEach(b => b.classList.remove('active'));
  }
});

// Init
renderCards();
</script>
